    18→const parseFunctionError = (error: any) => {
    19→  const message = error?.message || "";
    20→  const jsonStart = message.indexOf("{");
    21→  if (jsonStart === -1) return null;
    22→  try {
    23→    return JSON.parse(message.slice(jsonStart));
    24→  } catch {
    25→    return null;
    26→  }
    27→};
